import React, { useState } from 'react';
import './styles.css';

let nextId = 1;

const AMOUNT_PATTERN = /^\d+(\.\d{1,2})?$/;

export default function App() {
  const [note, setNote] = useState('');
  const [amount, setAmount] = useState('');
  const [category, setCategory] = useState('餐饮');
  const [expenses, setExpenses] = useState([]);
  const [error, setError] = useState('');

  function handleAdd() {
    const trimmedNote = note.trim();
    if (!trimmedNote) {
      setError('备注不能为空');
      return;
    }

    const rawAmount = amount.trim();
    if (!AMOUNT_PATTERN.test(rawAmount)) {
      setError('金额必须是大于 0 且最多两位小数的数字');
      return;
    }

    const numericAmount = Number(rawAmount);
    if (!(numericAmount > 0)) {
      setError('金额必须大于 0');
      return;
    }

    setError('');
    const record = {
      id: nextId++,
      note: trimmedNote,
      amount: numericAmount,
      category,
    };
    setExpenses([...expenses, record]);
  }

  return (
    <main className="app">
      <h1>本地记账表</h1>
      <div className="form">
        <label className="field">
          <span>备注</span>
          <input
            data-testid="note-input"
            value={note}
            onChange={(e) => setNote(e.target.value)}
            placeholder="例如：午餐"
          />
        </label>
        <label className="field">
          <span>金额</span>
          <input
            data-testid="amount-input"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            placeholder="例如：12.50"
          />
        </label>
        <label className="field">
          <span>分类</span>
          <select
            data-testid="category-select"
            value={category}
            onChange={(e) => setCategory(e.target.value)}
          >
            <option value="餐饮">餐饮</option>
            <option value="交通">交通</option>
          </select>
        </label>
        <button data-testid="add-button" onClick={handleAdd}>添加</button>
      </div>

      {error && (
        <p className="error" data-testid="error-message">{error}</p>
      )}

      <ul className="expense-list" data-testid="expense-list">
        {expenses.map((item) => (
          <li key={item.id} className="expense-item" data-testid="expense-item">
            <span className="item-note">{item.note}</span>
            <span className="item-amount">{item.amount.toFixed(2)}</span>
            <span className="item-category">{item.category}</span>
          </li>
        ))}
      </ul>
    </main>
  );
}

